// Iconos de la PWA (Look Makers) incrustados como data URI en base64.
// ICON_192/512 y el icono de Apple usan la nueva imagen de marca (ojo + sello Look Makers)
// enviada para reemplazar el icono anterior de la app. FAVICON reutiliza el icono de Apple
// (PNG) para asegurar compatibilidad en la pestana del navegador.

export const ICON_192_DATA_URI =
  "data:image/webp;base64,";

export const ICON_512_DATA_URI =
  "data:image/webp;base64,";

export const APPLE_TOUCH_ICON_DATA_URI =
  "data:image/png;base64,";

export const FAVICON_DATA_URI = APPLE_TOUCH_ICON_DATA_URI;
